//! 🗺️ A declared variant mapper owns its actual operation and outcome instead of an opaque fn(T)->U callback.
use super::*;
pub trait OwnedReceivingMap<T:RetireOwned>:Send+'static{type Output:RetireOwned;fn map_demand(input:&T)->Result<RetirementDemand,ValueError>;fn map_work_demand(_:&T)->Result<u64,ValueError>{Ok(1)}fn map_into(input:&mut Option<T>,output:&mut Option<Self::Output>,effect:&mut RetainedAllocationEffect<'_>)->OwnedTake;}
pub struct MappedReceiving<T:DslOwnedReceivingField,M:OwnedReceivingMap<T>>{current:OwnedSlot<FieldValue>,child_output:OwnedSlot<T>,output:OwnedSlot<M::Output>,child:OwnedReceivingSlot<T>,phase:u8,closing:bool,failed:bool,kind:std::marker::PhantomData<M>}
impl<T:DslOwnedReceivingField,M:OwnedReceivingMap<T>>MappedReceiving<T,M>{
 pub fn new()->Self{Self{current:Default::default(),child_output:Default::default(),output:Default::default(),child:OwnedReceivingSlot::new(),phase:0,closing:false,failed:false,kind:Default::default()}}
 fn selected(&mut self,source:&mut Option<FieldValue>,body:usize,effect:&mut RetainedAllocationEffect<'_>)->OwnedPoll{
  if self.failed||self.closing{return done(effect,Err(invariant().into()))}if self.phase==6{return idle(effect)}
  let d=match self.demands(source,body){Ok(d)=>d,Err(error)=>return done(effect,Err(error.into()))};if !admits(effect,d){return idle(effect)}
  let g=effect.grant();
  match self.phase{
   1 if !self.child.is_ready()=>{let poll=self.child.advance_local(&mut self.current.value,body,&mut effect.nested(child_grant(g)));return settle(effect,poll)},
   2 if self.child_output.value.is_none()=>{let poll=self.child.take_into(&mut self.child_output.value,&mut effect.nested(child_grant(g)));return settle(effect,normal(poll))},
   3 if !self.child.terminal_is_empty()=>{let poll=self.child.close_step(&mut effect.nested(child_grant(g)));return settle(effect,receiving(poll))},
   4 if self.output.value.is_none()=>{let poll=M::map_into(&mut self.child_output.value,&mut self.output.value,effect);return settle(effect,normal(poll))},
   5 if !self.current.terminal_is_empty()=>{let poll=self.current.close_step(effect);return settle(effect,receiving(poll))},
   _=>{}
  }
  local(effect,d,||{match self.phase{0=>{if source.is_none(){return Err(invalid())}*self.current.value=source.take();self.phase=1;},1=>self.phase=2,2=>self.phase=3,3=>self.phase=4,4=>self.phase=5,5=>self.phase=6,_=>return Err(invariant())}Ok(())})
 }
}
impl<T:DslOwnedReceivingField,M:OwnedReceivingMap<T>>OwnedFieldReceiving<M::Output>for MappedReceiving<T,M>{
 fn demands(&self,_:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.failed{return Err(invariant())}match self.phase{1 if !self.child.is_ready()=>self.child.demands(&self.current.value,body).and_then(nested),2 if self.child_output.value.is_none()=>nested(nested(metadata::<T>())?),3 if !self.child.terminal_is_empty()=>self.child.close_demands(body).and_then(nested),4 if self.output.value.is_none()=>M::map_demand(self.child_output.value.as_ref().ok_or_else(invariant)?),5 if !self.current.terminal_is_empty()=>self.current.close_demands(body),6=>Ok(Default::default()),_=>Ok(metadata::<()>())}}
 fn select_advance(&self,_:&Option<FieldValue>,body:usize,maximum_work_units:u64)->Result<OwnedAdvanceSelection,ValueError>{if self.closing||self.failed{return Err(invariant())}let local=|work:u64|Ok(OwnedAdvanceSelection::Local{work});match self.phase{1 if !self.child.is_ready()=>self.child.select_advance(&self.current.value,body,maximum_work_units),2 if self.child_output.value.is_none()=>local(self.child.take_work_demand()?),3 if !self.child.terminal_is_empty()=>local(self.child.close_work_demand(body)?),4 if self.output.value.is_none()=>local(M::map_work_demand(self.child_output.value.as_ref().ok_or_else(invariant)?)?),5 if !self.current.terminal_is_empty()=>local(self.current.close_work_demand(body)?),6=>local(0),_=>local(1)}}
 fn advance_nested(&mut self,_:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->OwnedPoll{if self.failed||self.closing||self.phase!=1||self.child.is_ready(){return RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invariant().into()),work:0})}let poll=self.child.advance_nested(&mut self.current.value,native,body,maximum_work_units,child_grant(g));poison(&mut self.failed,&poll);poll}
 fn advance_local(&mut self,source:&mut Option<FieldValue>,body:usize,effect:&mut RetainedAllocationEffect<'_>)->OwnedPoll{let poll=self.selected(source,body,effect);poison(&mut self.failed,&poll);poll}
 fn is_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==6&&self.output.value.is_some()}
 fn take_into(&mut self,output:&mut Option<M::Output>,effect:&mut RetainedAllocationEffect<'_>)->OwnedTake{if !self.is_ready(){return done(effect,Err(invariant()))}move_into(&mut self.output.value,output,effect)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if !self.child.terminal_is_empty(){return self.child.close_demands(body).and_then(nested)}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if !self.child_output.terminal_is_empty(){return self.child_output.close_demands(body)}self.output.close_demands(body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.terminal_is_empty(){return Ok(0)}if !self.closing{return Ok(1)}if !self.child.terminal_is_empty(){return self.child.close_work_demand(body)}if !self.current.terminal_is_empty(){return self.current.close_work_demand(body)}if !self.child_output.terminal_is_empty(){return self.child_output.close_work_demand(body)}self.output.close_work_demand(body)}
 fn close_step(&mut self,effect:&mut RetainedAllocationEffect<'_>)->OwnedClose{if self.terminal_is_empty(){return idle(effect)}let g=effect.grant();let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return done(effect,Err(error.into()))};if !admits(effect,d){return idle(effect)}if !self.closing{return local_close(effect,d,||{self.closing=true;Ok(())})}if !self.child.terminal_is_empty(){let poll=self.child.close_step(&mut effect.nested(child_grant(g)));return settle(effect,poll)}if !self.current.terminal_is_empty(){return self.current.close_step(effect)}if !self.child_output.terminal_is_empty(){return self.child_output.close_step(effect)}self.output.close_step(effect)}
 fn terminal_is_empty(&self)->bool{self.child.terminal_is_empty()&&self.current.terminal_is_empty()&&self.child_output.terminal_is_empty()&&self.output.terminal_is_empty()}
}
